  "designer.help.overview": "Build a reusable frontend template with approved shared controls. This designer saves demo drafts, not published backend DCP forms.",
  "designer.helpTitle.overview": "Overview",
  "designer.help.workflow": "Choose a section and add components from the palette. Drag handles or move buttons reorder items. Select a field to edit its label, required state, section, minimum or dropdown options. Preview uses temporary answers. Save design draft persists the design; Open saved design restores it.",
  "designer.helpTitle.workflow": "How to use this page",
  "designer.help.validation": "Designs require titles, unique stable IDs and valid dropdown options. Limits are 20 sections, 100 fields and 50 options per field. Failed saves retain edits and retries reuse the operation ID. Conflicts require reopening the latest saved design after reviewing unsaved changes.",
  "designer.helpTitle.validation": "Validation and recovery",
  "designer.help.access": "Only demo administrators can save designs. Drafts are isolated by tenant, application and user. Shared controls follow effective theme, density, typography and tenant locks. Preview does not save business answers or grant record access.",
  "designer.helpTitle.access": "Access and preferences",
  "designer.help.integration": "Inject DesignerAdapter and PreferenceHost into DcpDesignerWorkspace. The demo endpoint stores frontend template drafts in CSV snapshots. Backend DCP conversion, publication, datasets, rules and entity binding require the separate host adapter; no PostgreSQL or Java service is provisioned here.",
  "designer.helpTitle.integration": "Integration",
  "designer.help.preview": "After designing, select Live preview to try the current form without saving it. The preview shows the form title and hides editing controls. Validate preview checks your test answers. Reset preview clears only test answers; Design returns to editing and preserves the form. Preview answers never create business records.",
  "designer.dependsOn": "Depends on",
  "designer.independent": "Independent dropdown",
  "designer.mappingHelp": "Choose the parent value for each option below.",
  "designer.parentFor": "Parent value for {label}",
  "designer.parentProtected": "This field has dependent dropdowns. Remove their dependencies before deleting it.",
  "designer.dependencyInvalid": "Check dropdown dependencies: map every child option to an existing parent value. Parents must be dropdowns; cycles and chains deeper than five levels are not allowed.",
  "designer.chooseParent": "Select a valid parent option first.",
  "designer.lookupError": "Options could not be loaded. Retry to continue.",
  "designer.noOptions": "No options match this selection.",
  "designer.validating": "Validating with API…",
  "designer.countryExample": "Add Country → State example",
  "designer.location": "Location",
  "designer.country": "Country",
  "designer.state": "State / Emirate",
  "designer.india": "India",
  "designer.uae": "UAE",
  "designer.kerala": "Kerala",
  "designer.karnataka": "Karnataka",
  "designer.abuDhabi": "Abu Dhabi",
  "designer.dubai": "Dubai",
  "designer.help.dependencies": "For dependent dropdowns, create Country with IN|India and AE|UAE. Create State with KL|Kerala, KA|Karnataka, AZ|Abu Dhabi and DU|Dubai. In State properties choose Depends on: Country, then map KL/KA to IN and AZ/DU to AE. Or insert the API-provided Country → State example. Preview loads options from the API, disables children until a valid parent is selected, and clears all descendants on parent changes. Retry failed lookups without losing parent selections. Validate preview checks matching parent/child IDs on the demo API without saving answers. Cycles, missing parents, unmapped options and more than five dependency links are rejected. Company → Branch uses the same generic configuration. Dataset imports and multi-parent conditions are not included.",
